-- DEVELOPMENT ONLY. Refuse any non-development database.
BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
DO $$ BEGIN IF current_database() <> 'vrp_db_dev' THEN RAISE EXCEPTION 'refusing target %; expected vrp_db_dev', current_database(); END IF; PERFORM pg_advisory_xact_lock(hashtext('LGEAI:'||'Atlanta_3area')); END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM common_city_context WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area') AND (EXISTS (SELECT 1 FROM common_region_master WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area') OR EXISTS (SELECT 1 FROM common_technician_master WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area') OR EXISTS (SELECT 1 FROM common_technician_capability_master WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area')) THEN RAISE EXCEPTION 'target city has unmanaged existing data'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM common_city_context WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area' AND source_strategic_city_name <> 'Atlanta, GA') THEN RAISE EXCEPTION 'existing city source technician context differs'; END IF; IF EXISTS (SELECT 1 FROM common_region_plan WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area' AND plan_id='atlanta_3area_20260723' AND source_sha256 <> '7f861cd9000c6e2af6202f643184a376c4bcaef8ec6a02851fac76c5a0c11f4b') THEN RAISE EXCEPTION 'existing plan_id has different source checksum'; END IF; IF EXISTS (SELECT 1 FROM common_region_plan WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area' AND plan_id='atlanta_3area_20260723' AND bundle_sha256 IS NOT NULL AND bundle_sha256 <> 'e1ddd13c7ff1da3ce2898d1afbf9fabc3faa756cbdad0785fd8c20c5f7cf09af') THEN RAISE EXCEPTION 'existing plan_id has different canonical bundle'; END IF; END $$;
DO $$ BEGIN IF (SELECT count(*) FROM common_technician_master WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta, GA' AND employee_code IN ('AI102315','AI102961','AI103128','AI103264','AI005576','AI103317','AI103261','AI102977','AI102608','AI102087','AI102448','AI105116','AI103146') AND active_flag) <> 13 THEN RAISE EXCEPTION 'source technician roster missing/inactive'; END IF; END $$;
DELETE FROM common_technician_capability_master WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area';
DELETE FROM common_technician_master WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area';
DO $$ BEGIN IF (SELECT count(*) FROM common_region_plan_postal WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area' AND plan_id='atlanta_3area_20260723') <> 320 OR (SELECT count(*) FROM common_region_plan_technician WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area' AND plan_id='atlanta_3area_20260723') <> 13 THEN RAISE EXCEPTION 'plan child row counts do not match manifest'; END IF; END $$;
DELETE FROM common_region_master WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area';
UPDATE common_region_plan SET plan_status='reviewed',manifest_sha256='ed2f9c6862f6ee67c7f169c0ef0f0cc31a81fb94bb7a69feae6d8bc4a3bcb792',bundle_sha256='e1ddd13c7ff1da3ce2898d1afbf9fabc3faa756cbdad0785fd8c20c5f7cf09af',fixed_region_sha256='b644fad4190788c02ba3c4033000fe73694c58b11148a7d12ced4994bdd1f8f1',boundary_policy_sha256='6fe91798f1c369f4ed6328b53f9cdd5910201c65fe23156af5496f1d80e345dd',technician_policy_sha256='b28a8ef354d5dcc83512056c444c4c732e64940e4e85f0703604f401eac595c2',reviewed_by=current_user,review_reference='source=atlanta_3area_canonical_workbook.xlsx;sha256=7f861cd9000c6e2af6202f643184a376c4bcaef8ec6a02851fac76c5a0c11f4b',reviewed_at=now() WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area' AND plan_id='atlanta_3area_20260723';
UPDATE common_region_plan_activation SET active_flag=false,superseded_at=now() WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area' AND active_flag AND NOT EXISTS (SELECT 1 FROM common_region_plan_activation x WHERE x.subsidiary_name='LGEAI' AND x.strategic_city_name='Atlanta_3area' AND x.idempotency_key='atlanta_3area_20260723:activate:7f861cd9000c6e2af6202f643184a376c4bcaef8ec6a02851fac76c5a0c11f4b');
UPDATE common_region_plan SET plan_status='superseded' WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area' AND plan_status='active' AND plan_id <> 'atlanta_3area_20260723';
UPDATE common_region_plan SET plan_status='active' WHERE subsidiary_name='LGEAI' AND strategic_city_name='Atlanta_3area' AND plan_id='atlanta_3area_20260723';
UPDATE common_city_context c SET context_status='active',activation_revision=a.activation_revision FROM common_region_plan_activation a WHERE a.subsidiary_name='LGEAI' AND a.strategic_city_name='Atlanta_3area' AND a.active_flag AND c.subsidiary_name=a.subsidiary_name AND c.strategic_city_name=a.strategic_city_name;
COMMIT;
