INSERT INTO common_region_master (subsidiary_name,strategic_city_name,postal_code,region_seq,region_name,area_type) SELECT p.subsidiary_name,p.strategic_city_name,p.postal_code,p.region_seq,r.region_name,p.area_type FROM common_region_plan_postal p JOIN common_region_plan_region r USING (subsidiary_name,strategic_city_name,plan_id,region_seq) WHERE p.subsidiary_name='LGEAI' AND p.strategic_city_name='Atlanta_3area' AND p.plan_id='atlanta_3area_20260723';
INSERT INTO common_region_plan_activation (subsidiary_name,strategic_city_name,activation_revision,plan_id,plan_revision,verification_only,active_flag,preview_digest,idempotency_key,activated_by,activation_reference) SELECT 'LGEAI','Atlanta_3area',coalesce(max(a.activation_revision),0)+1,'atlanta_3area_20260723',p.revision,true,true,'e1ddd13c7ff1da3ce2898d1afbf9fabc3faa756cbdad0785fd8c20c5f7cf09af','atlanta_3area_20260723:activate:7f861cd9000c6e2af6202f643184a376c4bcaef8ec6a02851fac76c5a0c11f4b',current_user,'source=atlanta_3area_canonical_workbook.xlsx;sha256=7f861cd9000c6e2af6202f643184a376c4bcaef8ec6a02851fac76c5a0c11f4b' FROM common_region_plan p LEFT JOIN common_region_plan_activation a ON a.subsidiary_name='LGEAI' AND a.strategic_city_name='Atlanta_3area' WHERE p.subsidiary_name='LGEAI' AND p.strategic_city_name='Atlanta_3area' AND p.plan_id='atlanta_3area_20260723' AND NOT EXISTS (SELECT 1 FROM common_region_plan_activation x WHERE x.subsidiary_name='LGEAI' AND x.strategic_city_name='Atlanta_3area' AND x.idempotency_key='atlanta_3area_20260723:activate:7f861cd9000c6e2af6202f643184a376c4bcaef8ec6a02851fac76c5a0c11f4b') GROUP BY p.revision;
